"""Validation of a frozen repair against current measured inputs."""

from .common_utils import PPM
from .dtp import compute_predictions


def validate_snapshot(topology, state, settings, snapshot, identifier):
    """Compare published counter cells with current predicted loads.

    Every expected flow contributes its published cells whose frozen
    confidence reaches the cutoff: two reports for an internal flow and a
    single report for an external flow.  A check passes exactly when
    ``1000000*|X-Y| <= tau*max(X,Y)`` with ``X = corrected*1000000`` and
    ``Y = predicted*(1000000-bias)``.
    """
    predictions, routed = compute_predictions(topology, state.demands, state.routes)
    published = {}
    for key, value, numerator, denominator in snapshot[2]:
        published[key] = (value, numerator, denominator)

    cutoff_numerator = settings.cutoff_numerator
    cutoff_denominator = settings.cutoff_denominator
    bias = settings.bias
    tau = settings.tau
    gamma_numerator = settings.gamma_numerator
    gamma_denominator = settings.gamma_denominator

    checked = 0
    passed = 0
    failed = []
    for flow in topology.flows:
        source, target = flow
        if not routed and source >= 0 and target >= 0:
            # Without a routing plan an internal flow has no expectation.
            continue
        predicted = predictions[flow]
        scale = predicted * (PPM - bias)
        for key in topology.report_keys(flow):
            value, numerator, denominator = published[key]
            if numerator * cutoff_denominator < cutoff_numerator * denominator:
                continue
            checked += 1
            corrected = value * PPM
            if corrected >= scale:
                gap = corrected - scale
                bigger = corrected
            else:
                gap = scale - corrected
                bigger = scale
            if PPM * gap <= tau * bigger:
                passed += 1
            else:
                failed.append(key)
    failed.sort()
    if checked:
        consistent = passed * gamma_denominator >= gamma_numerator * checked
    else:
        consistent = None
    return {"op": "validate", "id": identifier, "checked": checked, "passed": passed,
            "consistent": consistent, "failed": failed}
